import {readFileSync} from 'node:fs';
new Function(readFileSync(new URL('../core/finance.js',import.meta.url),'utf8')+"\nconst a=(v,m)=>{if(!v)throw Error(m);};const r={id:'a',date:'2026-01-01',cents:10001,type:'Expense',category:'Fuel'};\na(Finance.cents('100.01')===10001,'cents');a(Finance.total([{...r,cents:10000,splits:[{cents:7000,category:'Principal',classification:'principal'},{cents:3000,category:'Interest',classification:'interest'}]}]).expense===3000,'split');a(Finance.total([r,Finance.reverse(r,'2026-02-01','b')]).expense===0,'reversal');a(Finance.occurrence({due:'2026-01-31',frequency:'Monthly'},1)==='2026-02-28','month end');a(Finance.occurrence({due:'2026-01-31',frequency:'Monthly'},2)==='2026-03-31','anchor');a(Finance.occurrences({due:'2026-01-01',frequency:'Custom days',interval:3},'2026-01-01','2026-01-10').length===4,'custom');a(Finance.duplicate({...r,id:'b'},[r])===r,'duplicate');a(!Finance.paid('x',[{...r,billKey:'x'},Finance.reverse(r,'2026-02-01','b')]),'reversed bill');a(Finance.csvParse('a,\"b,c\"\\r\\n1,\"x\"\"y\"')[1][1]==='x\"y','CSV');a(Finance.estimate({variable:'revenue',rate:5},10001)===500,'percentage');")();

new Function(readFileSync(new URL('../core/finance.js',import.meta.url),'utf8')+"\nconst ok=(v,m)=>{if(!v)throw Error(m)};const b={due:'2024-01-31',frequency:'Monthly'};ok(Finance.occurrence(b,1)==='2024-02-29','leap year');ok(Finance.occurrences({due:'2026-01-01',frequency:'Twice monthly'},'2026-01-01','2026-01-31').join(',')==='2026-01-01,2026-01-16','twice monthly');ok(Finance.occurrences({due:'2026-01-01',frequency:'Daily',status:'paused'},'2026-01-01','2026-01-10').length===0,'pause');ok(Finance.annual({frequency:'Weekly',amount:'100.01'})===520052,'annual');const r={id:'a',date:'2026-01-01',cents:100,type:'Expense',category:'Oil',classification:'expense',ref:'',note:''};ok(Finance.check({...r,party:'Vendor',audit:Finance.audit(r,'edited')}).party==='Vendor','edit');ok(Finance.total([{...r,classification:'principal'}]).net===0,'principal');")();

new Function(['core/occupations.js','core/finance.js','core/accounting.js','payments.js'].map(p=>readFileSync(new URL('../'+p,import.meta.url),'utf8')).join('\n')+"\nconst ok=(v,m)=>{if(!v)throw Error(m)};const r={id:'a',trade:'Trucking',type:'Expense',category:'Custom fuel',cents:12345,date:'2026-01-01',ref:'',note:'',classification:'expense',party:'Vendor'};const checked=validate([r])[0];ok(checked.party==='Vendor','preserve fields');ok(totals([checked]).expense===12345,'legacy total');ok(validate([{...checked,note:'Edited',audit:Finance.audit(checked,'edited')}])[0].audit.length===1,'edit audit');const paid=WorkPayments.rows([{id:'Q-123',customer:'Customer',paid:{date:'2026-01-02'},items:[{kind:'labor',qty:100,rate:5000}],tax:500}]);const t=Finance.total(paid);ok(t.income===5000&&t.cash===5500,'sales tax projection');ok(Finance.duplicate({...r,id:'b',source:'settlement',externalId:'123'},[{...r,source:'settlement',externalId:'123'}]),'external duplicate');")();

new Function(readFileSync(new URL('../core/finance.js',import.meta.url),'utf8')+`\nconst r={id:'mistake',date:'2026-01-01',type:'Expense',classification:'expense',cents:12500,category:'Parts'};const ok=(v,m)=>{if(!v)throw Error(m)};const c=Finance.correctMistake(r,{},[r],'offset');ok(c.date===r.date&&c.reversalOf===r.id&&Finance.total([r,c]).expense===0,'same-date correction');for(const p of [{scanner:{receipts:[{ledgerId:r.id}]}},{mechanic:{jobs:[{costs:[{ledgerId:r.id}]}]}},{trucking:{leases:[{payments:[{ledgerIds:[r.id]}]}]}}])ok(Finance.linkedForDeletion(r,p,[r]),'linked protected');ok(Finance.linkedForDeletion(r,{},[r,c]),'duplicate correction blocked');`)();

// Universal paid quote projections: explicit trade, original mechanic IDs preserved, sales tax excluded from profit.
new Function(['core/occupations.js','core/finance.js','core/accounting.js','payments.js'].map(p=>readFileSync(new URL('../'+p,import.meta.url),'utf8')).join('\n')+"\nconst q={id:'Q-123',customer:'Fixture',paid:{date:'2026-01-02'},items:[{kind:'labor',qty:100,rate:5000},{kind:'part',qty:100,rate:2000}],tax:500};for(const trade of ['Mechanic','Trucking','General contractor','Other business']){const rows=validate(WorkPayments.rows([{...q,trade}]));if(rows.some(r=>r.trade!==trade)||Finance.total(rows).income!==7000||Finance.total(rows).cash!==7500)throw Error('Quote projection '+trade);}if(JSON.stringify(WorkPayments.rows([q]))!==JSON.stringify(WorkPayments.rows([{...q,trade:'Mechanic'}])))throw Error('Changed legacy quote identity');")();

new Function(readFileSync(new URL('../core/finance.js',import.meta.url),'utf8')+`\nconst ok=(v,m)=>{if(!v)throw Error(m)};const r={id:'repair',date:'2026-01-01',trade:'Trucking',type:'Expense',category:'Repairs',cents:1000,classification:'expense',ref:'',note:'',party:'Vendor',audit:[]};ok(Finance.linkedForDeletion(r,{trucking:{maintenance:[{ledgerIds:[r.id]}]}},[r]),'maintenance link');const edit=Finance.editSimple(r,{cents:2000,party:'bad'}, {},[r]);ok(edit.party==='Vendor'&&edit.cents===2000&&edit.audit.length===1,'preserve metadata');ok(Finance.entryMode({...r,classification:'principal'}, {},[r])==='advanced','advanced mode');for(const [category,cash] of [['Maintenance escrow contribution',-1000],['Tire escrow release',1000],['Truck principal',-1000]]){const t=Finance.total([{...r,classification:undefined,type:'Transfer',category}]);ok(t.cash===cash&&t.net===0,'legacy transfer '+category);}`)();
